const now=new Date();let state=normalize(loadState()),role='viewer',sessionPin='',currentEmployeeId='',cloudSaveTimer,currentMonth=new Date(now.getFullYear(),now.getMonth(),1),selectedDay=now.getDate(),filter='active';
function loadState(){try{const s=JSON.parse(localStorage.getItem(STORE_KEY));if(s?.employees)return s}catch{}return{employees:INITIAL_EMPLOYEES,settings:{restTarget:8,minStaff:3,pairA:'',pairB:''},schedules:{}}}
function normalize(s){s.settings={restTarget:8,minStaff:3,pairA:'',pairB:'',...(s.settings||{})};s.schedules??={};s.assignments??={};s.leaveRequests??=[];s.auditLog??=[];return s}
async function cloudRequest(name,body){const response=await fetch(`${SUPABASE_URL}/rest/v1/rpc/${name}`,{method:'POST',headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error('cloud request failed');return response.json()}
async function loadCloud(pin){state=normalize(await cloudRequest('load_schedule',{p_password:pin}));if(!state?.employees)throw new Error('invalid cloud data');currentEmployeeId=state.sessionEmployeeId||'';delete state.sessionEmployeeId;localStorage.setItem(STORE_KEY,JSON.stringify(state))}
function save(){localStorage.setItem(STORE_KEY,JSON.stringify(state));if(role!=='admin'||!sessionPin)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(()=>cloudRequest('save_schedule',{p_password:sessionPin,p_data:state}).catch(()=>showToast('雲端儲存失敗，請檢查網路')),350)}
function monthKey(date=currentMonth){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`}
function daysInMonth(){return new Date(currentMonth.getFullYear(),currentMonth.getMonth()+1,0).getDate()}
function schedule(){state.schedules[monthKey()]??={};return state.schedules[monthKey()]}
function assignments(){state.assignments[monthKey()]??={};return state.assignments[monthKey()]}
function employee(id){return state.employees.find(e=>e.id===id)}function activeEmployees(){return state.employees.filter(e=>e.active)}function activeFulltime(){return activeEmployees().filter(e=>e.type==='fulltime')}
function assignment(id,day){return assignments()[id]?.[day]||null}function statusFor(e,day){const a=assignment(e.id,day);if(a)return a.status;if(e.type==='pt')return'off';return schedule()[e.id]?.includes(day)?'off':'work'}
function shiftFor(e,day){const a=assignment(e.id,day);return{status:statusFor(e,day),start:a?.start||e.start,end:a?.end||e.end,note:a?.note||''}}
function setAssignment(id,day,data,action='手動調整班別'){const e=employee(id);assignments()[id]??={};assignments()[id][day]={...shiftFor(e,day),...data};schedule()[id]??=[];schedule()[id]=data.status==='off'?[...new Set([...schedule()[id],day])]:schedule()[id].filter(d=>d!==day);audit(action,`${e.name} ${monthKey()}-${String(day).padStart(2,'0')}：${data.status==='off'?'休假／未排班':`${data.start||e.start}–${data.end||e.end}`}${data.note?`（${data.note}）`:''}`);save();renderAll()}
function isRest(id,day){const e=employee(id);return!e||statusFor(e,day)==='off'}function setRest(id,day,value){const e=employee(id);setAssignment(id,day,{...shiftFor(e,day),status:value?'off':'work'},'總表快速調整')}
function restCount(id){const e=employee(id);let n=0;for(let d=1;d<=daysInMonth();d++)if(statusFor(e,d)==='off')n++;return n}function workCount(id){const e=employee(id);let n=0;for(let d=1;d<=daysInMonth();d++)if(statusFor(e,d)==='work')n++;return n}
function staffOnDay(day){return activeFulltime().filter(e=>statusFor(e,day)==='work').length}function warningDays(){let n=0;for(let d=1;d<=daysInMonth();d++)if(staffOnDay(d)<state.settings.minStaff)n++;return n}
function minutes(v){const[h,m]=v.split(':').map(Number);return h*60+m}function overlaps(a,b){return a.status==='work'&&b.status==='work'&&minutes(a.start)<minutes(b.end)&&minutes(b.start)<minutes(a.end)}
function pairConflict(day,changingId='',candidate=null){const a=employee(state.settings.pairA),b=employee(state.settings.pairB);if(!a||!b||!a.active||!b.active)return false;return overlaps(changingId===a.id?candidate:shiftFor(a,day),changingId===b.id?candidate:shiftFor(b,day))}
function pairConflictDays(){let n=0;for(let d=1;d<=daysInMonth();d++)if(pairConflict(d))n++;return n}
function audit(action,detail){state.auditLog.unshift({id:crypto.randomUUID?.()||`a${Date.now()}`,at:new Date().toISOString(),actor:role==='admin'?'Admin':employee(currentEmployeeId)?.name||'員工',action,detail});state.auditLog=state.auditLog.slice(0,100)}
function showToast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
function enter(nextRole){role=nextRole;document.querySelector('#login').hidden=true;document.querySelector('#app').hidden=false;document.querySelectorAll('.admin-only').forEach(el=>el.hidden=role!=='admin');renderAll()}
document.querySelector('#login-form').addEventListener('submit',async e=>{e.preventDefault();const pin=document.querySelector('#pin'),error=document.querySelector('#pin-error'),button=e.currentTarget.querySelector('button');if(!/^\d{4}$/.test(pin.value)){error.textContent='請輸入四位數密碼。';error.hidden=false;pin.setAttribute('aria-invalid','true');pin.select();pin.focus();return}button.disabled=true;button.textContent='連接雲端中…';try{await loadCloud(pin.value);const nextRole=pin.value==='8888'?'admin':'viewer';if(nextRole==='viewer'&&!currentEmployeeId)throw new Error('employee identity missing');sessionPin=pin.value;error.hidden=true;pin.removeAttribute('aria-invalid');enter(nextRole)}catch{currentEmployeeId='';error.textContent='密碼不正確，請重新輸入。';error.hidden=false;pin.setAttribute('aria-invalid','true');pin.select()}finally{button.disabled=false;button.textContent='登入'}});
document.querySelector('#logout').addEventListener('click',()=>{sessionPin='';currentEmployeeId='';document.querySelector('#app').hidden=true;document.querySelector('#login').hidden=false;const p=document.querySelector('#pin');p.value='';p.removeAttribute('aria-invalid');document.querySelector('#pin-error').hidden=true;p.focus()});
const titles={dashboard:'本月總覽',calendar:'月曆班表',requests:'休假申請',employees:'員工管理',settings:'排班設定'};document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item,.page').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector(`#${b.dataset.page}`).classList.add('active');document.querySelector('#page-title').textContent=titles[b.dataset.page];window.scrollTo({top:0,behavior:'smooth'})}));document.querySelectorAll('[data-month]').forEach(b=>b.addEventListener('click',()=>{currentMonth=new Date(currentMonth.getFullYear(),currentMonth.getMonth()+Number(b.dataset.month),1);selectedDay=1;renderAll()}));
function renderAll(){renderDashboard();renderCalendar();renderSummary();renderEmployees();renderRequests();renderSettings()}
function renderDashboard(){const full=activeFulltime(),target=state.settings.restTarget;document.querySelector('#month-label').textContent=`${currentMonth.getFullYear()} 年 ${currentMonth.getMonth()+1} 月`;document.querySelector('#fulltime-count').textContent=full.length;document.querySelector('#goal-count').textContent=full.filter(e=>restCount(e.id)>=target).length;document.querySelector('#warning-count').textContent=warningDays()+pairConflictDays();document.querySelector('#goal-list').innerHTML=full.map(e=>{const count=restCount(e.id),pct=Math.min(100,count/target*100);return`<div class="goal-row"><div class="avatar">${e.name.slice(-1)}</div><div class="goal-info"><strong>${e.name}</strong><small>${workCount(e.id)} 個工作天 · ${e.start}–${e.end}</small><div class="progress" aria-label="已休 ${count} 天，共 ${target} 天"><span style="width:${pct}%"></span></div></div><span class="goal-value ${count<target?'missing':''}">${count}/${target}</span></div>`}).join('')||'<p class="muted">尚無正職員工。</p>'}
document.querySelector('#auto-schedule').addEventListener('click',()=>{const full=activeFulltime(),target=state.settings.restTarget,maxOff=Math.max(0,full.length-state.settings.minStaff);if(!full.length||maxOff===0){showToast('最低人數設定過高，無法自動排休');return}state.schedules[monthKey()]={};state.assignments[monthKey()]={};let cursor=0;for(const e of full){schedule()[e.id]=[];let tries=0;while(schedule()[e.id].length<target&&tries<daysInMonth()*4){const day=(cursor%daysInMonth())+1,offToday=full.filter(x=>(schedule()[x.id]||[]).includes(day)).length;if(offToday<maxOff)schedule()[e.id].push(day);cursor+=2;tries++}cursor++}audit('產生建議排休',`${monthKey()}，正職月休目標 ${target} 天`);save();renderAll();showToast('已產生建議排休，請確認人力與搭班警示')});
function renderCalendar(){const y=currentMonth.getFullYear(),m=currentMonth.getMonth(),first=new Date(y,m,1).getDay();document.querySelector('#calendar-title').textContent=`${y} 年 ${m+1} 月`;let html='';for(let i=0;i<first;i++)html+='<span class="calendar-day blank"></span>';for(let d=1;d<=daysInMonth();d++){const off=activeFulltime().filter(e=>statusFor(e,d)==='off').length,warn=staffOnDay(d)<state.settings.minStaff||pairConflict(d),today=y===now.getFullYear()&&m===now.getMonth()&&d===now.getDate();html+=`<button class="calendar-day ${today?'today':''} ${selectedDay===d?'selected':''} ${warn?'warning':''}" data-day="${d}" aria-label="${m+1}月${d}日，${off}人休假${warn?'，有警示':''}"><span>${d}</span>${off?`<span class="off-count">休 ${off}</span>`:''}</button>`}document.querySelector('#calendar-grid').innerHTML=html;document.querySelectorAll('.calendar-day[data-day]').forEach(b=>b.addEventListener('click',()=>{selectedDay=Number(b.dataset.day);renderCalendar()}));renderDayDetail()}
function renderDayDetail(){const warning=staffOnDay(selectedDay)<state.settings.minStaff,conflict=pairConflict(selectedDay);document.querySelector('#day-detail').innerHTML=`<h3>${currentMonth.getMonth()+1} 月 ${selectedDay} 日</h3><p class="${warning||conflict?'field-error':'muted'}">正職到班 ${staffOnDay(selectedDay)} 人／最低 ${state.settings.minStaff} 人${warning?'，人力不足':''}${conflict?'；指定兩人班別時間重疊':''}</p>${activeEmployees().map(e=>{const s=shiftFor(e,selectedDay);return`<div class="day-person"><div><strong>${e.name} <small>${e.type==='fulltime'?'正職':'PT'}</small></strong><div class="muted">${s.status==='work'?`${s.start}–${s.end}`:'休假／未排班'}</div></div>${role==='admin'?`<button class="mini-button ${s.status==='off'?'rest':''}" data-edit-shift="${e.id}">編輯</button>`:`<span class="status-badge ${s.status==='off'?'rest':''}">${s.status==='work'?'上班':'休'}</span>`}</div>`}).join('')}`;document.querySelectorAll('[data-edit-shift]').forEach(b=>b.addEventListener('click',()=>openShift(b.dataset.editShift,selectedDay)))}
function renderSummary(){const items=activeEmployees();let html='<thead><tr><th class="name-cell" scope="col">姓名</th>';for(let d=1;d<=daysInMonth();d++)html+=`<th scope="col">${d}</th>`;html+='<th class="total-cell" scope="col">工</th></tr></thead><tbody>';for(const e of items){html+=`<tr><th class="name-cell" scope="row">${e.name}<small>${e.type==='fulltime'?'正':'PT'}</small></th>`;for(let d=1;d<=daysInMonth();d++){const off=statusFor(e,d)==='off';html+=`<td><button class="roster-cell ${off?'rest':''}" data-roster-id="${e.id}" data-roster-day="${d}" aria-label="${e.name} ${currentMonth.getMonth()+1}月${d}日 ${off?'休假或未排班':'上班'}" ${role!=='admin'?'disabled':''}>${off?'休':'·'}</button></td>`}html+=`<td class="total-cell">${workCount(e.id)}</td></tr>`}document.querySelector('#roster-table').innerHTML=html+'</tbody>';document.querySelectorAll('[data-roster-id]').forEach(b=>b.addEventListener('click',()=>setRest(b.dataset.rosterId,Number(b.dataset.rosterDay),!isRest(b.dataset.rosterId,Number(b.dataset.rosterDay)))))}
document.querySelector('#clear-schedule').addEventListener('click',()=>{if(confirm('要清除這個月所有排休與班別調整嗎？')){state.schedules[monthKey()]={};state.assignments[monthKey()]={};audit('清除月班表',monthKey());save();renderAll();showToast('本月班表已清除')}});
function renderEmployees(){const items=state.employees.filter(e=>filter==='all'||e.active);document.querySelector('#employee-list').innerHTML=items.map(e=>`<article class="employee-card ${e.active?'':'inactive'}"><div class="avatar">${e.name.slice(-1)}</div><div><h3>${e.name} <small>${e.type==='fulltime'?'正職':'PT'}</small></h3><p>${e.start}–${e.end}${e.note?` · ${e.note}`:''}</p></div><div class="employee-actions admin-only" ${role!=='admin'?'hidden':''}><button class="mini-button" data-edit="${e.id}">編輯</button><button class="mini-button" data-active="${e.id}">${e.active?'停用':'恢復'}</button></div></article>`).join('');document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>openEmployee(b.dataset.edit)));document.querySelectorAll('[data-active]').forEach(b=>b.addEventListener('click',()=>{const e=employee(b.dataset.active);e.active=!e.active;audit(e.active?'恢復員工':'停用員工',e.name);save();renderAll();showToast(e.active?'員工已恢復':'員工已停用，歷史班表保留')}))}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));renderEmployees()}));
const dialog=document.querySelector('#employee-dialog');function openEmployee(id){const e=employee(id);document.querySelector('#dialog-title').textContent=e?'編輯員工':'新增員工';document.querySelector('#employee-id').value=e?.id||'';document.querySelector('#employee-name').value=e?.name||'';document.querySelector('#employee-type').value=e?.type||'fulltime';document.querySelector('#start-time').value=e?.start||'09:00';document.querySelector('#end-time').value=e?.end||'21:00';document.querySelector('#employee-note').value=e?.note||'';document.querySelector('#employee-pin').value='';document.querySelector('#employee-pin').required=!e;dialog.showModal()}
document.querySelector('#add-employee').addEventListener('click',()=>openEmployee());document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());document.querySelector('#employee-form').addEventListener('submit',async e=>{e.preventDefault();const id=document.querySelector('#employee-id').value,pin=document.querySelector('#employee-pin').value,data={name:document.querySelector('#employee-name').value.trim(),type:document.querySelector('#employee-type').value,start:document.querySelector('#start-time').value,end:document.querySelector('#end-time').value,note:document.querySelector('#employee-note').value.trim()};if(!data.name||(!id&&!/^\d{4}$/.test(pin))||(pin&&!/^\d{4}$/.test(pin))){showToast('員工密碼必須是四位數字');return}const found=employee(id),employeeId=found?.id||`e${Date.now()}`,button=e.currentTarget.querySelector('button');if(found){Object.assign(found,data);audit('修改員工資料',data.name)}else{state.employees.push({id:employeeId,...data,active:true});audit('新增員工',data.name)}button.disabled=true;button.textContent='儲存中…';try{await cloudRequest('save_schedule',{p_password:sessionPin,p_data:state});if(pin)await cloudRequest('set_employee_pin',{p_password:sessionPin,p_employee_id:employeeId,p_employee_pin:pin});localStorage.setItem(STORE_KEY,JSON.stringify(state));dialog.close();renderAll();showToast(pin?'員工資料與個人密碼已儲存':'員工資料已儲存')}catch{showToast('儲存失敗，請檢查網路後重試')}finally{button.disabled=false;button.textContent='儲存員工'}});
function renderRequests(){const requests=role==='admin'?state.leaveRequests:state.leaveRequests.filter(r=>r.employeeId===currentEmployeeId);document.querySelector('#request-list-title').textContent=role==='admin'?'全部申請':'我的申請';document.querySelector('#leave-form').hidden=role==='admin';document.querySelector('#request-list').innerHTML=requests.length?[...requests].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(r=>`<article class="request-card"><div><strong>${employee(r.employeeId)?.name||'已離職員工'} · ${r.date}</strong><p>${r.reason||'未填原因'}</p><span class="status-badge ${r.status}">${{pending:'待核准',approved:'已核准',rejected:'未核准'}[r.status]}</span></div>${role==='admin'&&r.status==='pending'?`<div class="request-actions"><button class="mini-button approve" data-request="${r.id}" data-decision="approved">核准</button><button class="mini-button" data-request="${r.id}" data-decision="rejected">不核准</button></div>`:''}</article>`).join(''):'<p class="muted">目前沒有休假申請。</p>';document.querySelectorAll('[data-decision]').forEach(b=>b.addEventListener('click',()=>decideRequest(b.dataset.request,b.dataset.decision)))}
document.querySelector('#leave-form').addEventListener('submit',async e=>{e.preventDefault();const date=document.querySelector('#leave-date').value,reason=document.querySelector('#leave-reason').value.trim(),button=e.currentTarget.querySelector('button');if(!currentEmployeeId||!date)return;button.disabled=true;button.textContent='送出中…';try{await cloudRequest('submit_leave_request',{p_password:sessionPin,p_employee_id:currentEmployeeId,p_date:date,p_reason:reason});await loadCloud(sessionPin);e.currentTarget.reset();renderAll();showToast('休假申請已送出，等待 Admin 核准')}catch{showToast('申請送出失敗，請檢查網路後重試')}finally{button.disabled=false;button.textContent='送出申請'}});
function decideRequest(id,decision){const r=state.leaveRequests.find(x=>x.id===id);if(!r)return;r.status=decision;r.decidedAt=new Date().toISOString();if(decision==='approved'){const date=new Date(`${r.date}T12:00:00`),oldMonth=currentMonth;currentMonth=new Date(date.getFullYear(),date.getMonth(),1);setAssignment(r.employeeId,date.getDate(),{...shiftFor(employee(r.employeeId),date.getDate()),status:'off',note:'Admin 核准休假'},'核准休假申請');currentMonth=oldMonth;renderAll()}else{audit('不核准休假申請',`${employee(r.employeeId)?.name} ${r.date}`);save();renderAll()}showToast(decision==='approved'?'已核准並寫入班表':'申請已標記為未核准')}
const shiftDialog=document.querySelector('#shift-dialog');function openShift(id,day){const e=employee(id),s=shiftFor(e,day);document.querySelector('#shift-dialog-title').textContent=`${e.name} · ${currentMonth.getMonth()+1}/${day}`;document.querySelector('#shift-employee-id').value=id;document.querySelector('#shift-day').value=day;document.querySelector('#shift-status').value=s.status;document.querySelector('#shift-start').value=s.start;document.querySelector('#shift-end').value=s.end;document.querySelector('#shift-note').value='';document.querySelector('#shift-warning').hidden=true;shiftDialog.showModal()}
document.querySelector('#close-shift-dialog').addEventListener('click',()=>shiftDialog.close());document.querySelector('#shift-form').addEventListener('submit',e=>{e.preventDefault();const id=document.querySelector('#shift-employee-id').value,day=Number(document.querySelector('#shift-day').value),candidate={status:document.querySelector('#shift-status').value,start:document.querySelector('#shift-start').value,end:document.querySelector('#shift-end').value,note:document.querySelector('#shift-note').value.trim()},warning=document.querySelector('#shift-warning');if(candidate.status==='work'&&(!candidate.start||!candidate.end||minutes(candidate.start)>=minutes(candidate.end))){warning.textContent='請輸入有效的上下班時間。';warning.hidden=false;return}if(pairConflict(day,id,candidate)&&!candidate.note){warning.textContent='這個班別與指定搭班人員時間重疊。Admin 可覆寫，但請先填寫修改原因。';warning.hidden=false;return}setAssignment(id,day,candidate,pairConflict(day,id,candidate)?'覆寫搭班重疊':'手動編輯班別');shiftDialog.close();showToast('班別已儲存')});
function renderSettings(){document.querySelector('#rest-target').value=state.settings.restTarget;document.querySelector('#min-staff').value=state.settings.minStaff;const opts='<option value="">不設定</option>'+activeEmployees().map(e=>`<option value="${e.id}">${e.name}</option>`).join('');const a=document.querySelector('#pair-a'),b=document.querySelector('#pair-b');a.innerHTML=opts;b.innerHTML=opts;a.value=state.settings.pairA||'';b.value=state.settings.pairB||'';document.querySelectorAll('#settings-form input,#settings-form select').forEach(x=>x.disabled=role!=='admin');document.querySelector('#audit-list').innerHTML=role==='admin'?(state.auditLog.slice(0,20).map(x=>`<article class="audit-row"><strong>${x.action}</strong><p>${x.detail}</p><small>${x.actor} · ${new Date(x.at).toLocaleString('zh-TW')}</small></article>`).join('')||'<p class="muted">尚無修改紀錄。</p>'):'<p class="muted">只有 Admin 可以查看修改紀錄。</p>'}
document.querySelector('#settings-form').addEventListener('submit',e=>{e.preventDefault();const pairA=document.querySelector('#pair-a').value,pairB=document.querySelector('#pair-b').value;if(pairA&&pairA===pairB){showToast('搭班限制必須選擇兩位不同員工');return}state.settings.restTarget=Number(document.querySelector('#rest-target').value);state.settings.minStaff=Number(document.querySelector('#min-staff').value);state.settings.pairA=pairA;state.settings.pairB=pairB;audit('修改排班設定',`月休 ${state.settings.restTarget} 天；最低 ${state.settings.minStaff} 人；搭班 ${employee(pairA)?.name||'未設定'}／${employee(pairB)?.name||'未設定'}`);save();renderAll();showToast('排班設定已儲存')});
document.querySelector('#leave-date').min=new Date().toISOString().slice(0,10);if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));setInterval(async()=>{if(role!=='viewer'||!sessionPin||document.querySelector('#app').hidden)return;try{await loadCloud(sessionPin);renderAll()}catch{}},30000);
